            if(prefix[i]==0) diffs.add(Math.abs(data[i]-data[i+1]));
        }
        Collections.sort(diffs);
        int total=0, sum=0;
        for(int d:diffs)
        {
            if(sum+d<=b){sum+=d; total++;}
            if(sum>=b) break;
        }
        System.out.print(total);
    }
}
